"use client";

import React, { useState, useRef, useEffect } from "react";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

export interface CreepyGlitchButtonProps {
  text?: string;
  hoverText?: string;
  onClick?: () => void;
  className?: string;
}

export function CreepyGlitchButton({
  text = "SYSTEM OVERRIDE",
  hoverText = "OVERRIDE ENGAGED",
  onClick,
  className,
}: CreepyGlitchButtonProps) {
  const [isHovered, setIsHovered] = useState(false);
  const [isBlinking, setIsBlinking] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [displayText, setDisplayText] = useState(text);

  const buttonRef = useRef<HTMLButtonElement>(null);

  // 1. Real-Time Screen Cursor Tracking
  useEffect(() => {
    const handleGlobalMouseMove = (e: MouseEvent) => {
      if (!buttonRef.current) return;
      const rect = buttonRef.current.getBoundingClientRect();
      const btnCenterX = rect.left + rect.width / 2;
      const btnCenterY = rect.top + rect.height / 2;

      const dx = e.clientX - btnCenterX;
      const dy = e.clientY - btnCenterY;

      // Clamp pupil translation matrix (-1 to 1)
      const maxOffset = 360;
      const normX = Math.max(-1, Math.min(1, dx / maxOffset));
      const normY = Math.max(-1, Math.min(1, dy / maxOffset));

      setMousePos({ x: normX, y: normY });
    };

    window.addEventListener("mousemove", handleGlobalMouseMove);
    return () => window.removeEventListener("mousemove", handleGlobalMouseMove);
  }, []);

  // 2. Biological Blinking Rhythm
  useEffect(() => {
    let blinkTimeout: NodeJS.Timeout;
    const scheduleBlink = () => {
      const delay = Math.random() * 2400 + 3200;
      blinkTimeout = setTimeout(() => {
        setIsBlinking(true);
        setTimeout(() => {
          setIsBlinking(false);
          scheduleBlink();
        }, 140);
      }, delay);
    };

    scheduleBlink();
    return () => clearTimeout(blinkTimeout);
  }, []);

  // 3. Text Glitch Scramble
  useEffect(() => {
    if (!isHovered) {
      setDisplayText(text);
      return;
    }

    const chars = "☠#@!⚡OVERRIDE";
    let iteration = 0;
    const interval = setInterval(() => {
      setDisplayText(
        hoverText
          .split("")
          .map((char, index) => {
            if (index < iteration) return hoverText[index];
            return chars[Math.floor(Math.random() * chars.length)];
          })
          .join("")
      );

      if (iteration >= hoverText.length) clearInterval(iteration);
      iteration += 1 / 2;
    }, 30);

    return () => clearInterval(interval);
  }, [isHovered, text, hoverText]);

  return (
    <div className={cn("relative flex flex-col items-center justify-center p-12 select-none", className)}>
      {/* ================= INCREASED HEIGHT ANIME EYES VECTOR (Matching Reference 100%) ================= */}
      <div className="relative mb-6 flex items-center justify-center w-96 h-40">
        <svg viewBox="0 0 460 200" className="w-full h-full filter drop-shadow-[0_12px_30px_rgba(0,0,0,0.95)]">
          <defs>
            {/* Rich Hazel-Brown Iris Gradient */}
            <radialGradient id="tallHazelIris" cx="40%" cy="38%" r="60%">
              <stop offset="0%" stopColor="#d97706" />
              <stop offset="40%" stopColor="#92400e" />
              <stop offset="80%" stopColor="#451a03" />
              <stop offset="100%" stopColor="#1c0a00" />
            </radialGradient>

            {/* Soft Eyeshadow Tint */}
            <linearGradient id="tallEyeshadow" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#f59e0b" stopOpacity="0.3" />
              <stop offset="100%" stopColor="#f59e0b" stopOpacity="0" />
            </linearGradient>
          </defs>

          {/* ================= LEFT ANIME EYE (TALLER HEIGHT) ================= */}
          <g transform="translate(45, 10)">
            {/* High-Visibility Bold Arched Eyebrow */}
            <path
              d="M 10 25 Q 55 2 100 18 C 75 14 45 15 10 25 Z"
              fill="#f8fafc"
            />
            <path
              d="M 82 15 L 88 23 M 86 14 L 91 21 M 89 14 L 93 19"
              stroke="#f8fafc"
              strokeWidth="2.5"
              strokeLinecap="round"
            />

            {/* Upper Eyeshadow Soft Contour */}
            <path
              d="M 15 65 Q 55 32 95 65 Q 55 42 15 65 Z"
              fill="url(#tallEyeshadow)"
            />

            {/* Solid White Sclera with Tall Curved Height */}
            <g clipPath="url(#tallLeftClip)">
              <clipPath id="tallLeftClip">
                <path d="M 15 68 Q 55 36 95 68 Q 55 100 15 68 Z" />
              </clipPath>

              {/* Solid White Sclera Fill */}
              <path d="M 15 68 Q 55 36 95 68 Q 55 100 15 68 Z" fill="#ffffff" />

              {/* Cursor Tracking Iris Assembly */}
              <motion.g
                animate={{
                  x: mousePos.x * 14,
                  y: mousePos.y * 10,
                }}
                transition={{ type: "spring", stiffness: 420, damping: 26 }}
              >
                {/* Limbal Outer Ring */}
                <circle cx="55" cy="68" r="18" fill="#1c0a00" />
                {/* Hazel Iris */}
                <circle cx="55" cy="68" r="16.5" fill="url(#tallHazelIris)" />
                {/* Inner Iris Ring */}
                <circle cx="55" cy="68" r="12" fill="#451a03" />
                {/* Black Pupil */}
                <circle cx="55" cy="68" r="7.5" fill="#000000" />
                {/* Main Specular Highlight Dot */}
                <circle cx="60" cy="63" r="4" fill="#ffffff" />
                {/* Secondary Specular Highlight Dot */}
                <circle cx="50" cy="73" r="2" fill="#ffffff" opacity="0.85" />
              </motion.g>
            </g>

            {/* Eyelid Blink Cover */}
            <motion.path
              d="M 15 68 Q 55 36 95 68 Q 55 100 15 68 Z"
              fill="#09090b"
              animate={{ scaleY: isBlinking ? 1 : 0 }}
              transition={{ duration: 0.12 }}
              style={{ transformOrigin: "center center" }}
            />

            {/* Upper Winged Black Eyeliner & Lashes */}
            <path
              d="M 10 68 Q 55 34 98 65 C 104 63 110 59 114 54 Q 100 64 93 67 Z"
              fill="#f8fafc"
            />
            {/* Eyelash Strokes */}
            <path
              d="M 36 51 Q 38 41 42 38 M 58 48 Q 61 38 66 35 M 78 52 Q 83 43 89 40 M 94 57 Q 100 48 106 46"
              stroke="#f8fafc"
              strokeWidth="2.5"
              strokeLinecap="round"
            />

            {/* Lower Lash Line & Dashes */}
            <path
              d="M 25 78 Q 55 92 85 78"
              stroke="#f8fafc"
              strokeWidth="2"
              fill="none"
              strokeDasharray="3,5"
            />
          </g>

          {/* ================= RIGHT ANIME EYE (TALLER HEIGHT) ================= */}
          <g transform="translate(225, 10)">
            {/* High-Visibility Bold Arched Eyebrow */}
            <path
              d="M 10 18 Q 55 2 100 25 C 65 15 35 14 10 18 Z"
              fill="#f8fafc"
            />
            <path
              d="M 12 20 L 17 12 M 17 22 L 22 13 M 21 23 L 26 14"
              stroke="#f8fafc"
              strokeWidth="2.5"
              strokeLinecap="round"
            />

            {/* Upper Eyeshadow Soft Contour */}
            <path
              d="M 5 65 Q 45 32 85 65 Q 45 42 5 65 Z"
              fill="url(#tallEyeshadow)"
            />

            {/* Solid White Sclera with Tall Curved Height */}
            <g clipPath="url(#tallRightClip)">
              <clipPath id="tallRightClip">
                <path d="M 5 68 Q 45 36 85 68 Q 45 100 5 68 Z" />
              </clipPath>

              {/* Solid White Sclera Fill */}
              <path d="M 5 68 Q 45 36 85 68 Q 45 100 5 68 Z" fill="#ffffff" />

              {/* Cursor Tracking Iris Assembly */}
              <motion.g
                animate={{
                  x: mousePos.x * 14,
                  y: mousePos.y * 10,
                }}
                transition={{ type: "spring", stiffness: 420, damping: 26 }}
              >
                {/* Limbal Outer Ring */}
                <circle cx="45" cy="68" r="18" fill="#1c0a00" />
                {/* Hazel Iris */}
                <circle cx="45" cy="68" r="16.5" fill="url(#tallHazelIris)" />
                {/* Inner Iris Ring */}
                <circle cx="45" cy="68" r="12" fill="#451a03" />
                {/* Black Pupil */}
                <circle cx="45" cy="68" r="7.5" fill="#000000" />
                {/* Main Specular Highlight Dot */}
                <circle cx="50" cy="63" r="4" fill="#ffffff" />
                {/* Secondary Specular Highlight Dot */}
                <circle cx="40" cy="73" r="2" fill="#ffffff" opacity="0.85" />
              </motion.g>
            </g>

            {/* Eyelid Blink Cover */}
            <motion.path
              d="M 5 68 Q 45 36 85 68 Q 45 100 5 68 Z"
              fill="#09090b"
              animate={{ scaleY: isBlinking ? 1 : 0 }}
              transition={{ duration: 0.12 }}
              style={{ transformOrigin: "center center" }}
            />

            {/* Upper Winged Black Eyeliner & Lashes */}
            <path
              d="M 2 65 Q 45 34 88 68 Q 82 66 76 66 C 80 58 84 55 88 52 Z"
              fill="#f8fafc"
            />
            {/* Eyelash Strokes */}
            <path
              d="M 18 57 Q 21 48 25 46 M 38 50 Q 41 38 45 35 M 58 51 Q 61 38 65 35 M 75 57 Q 80 48 85 46"
              stroke="#f8fafc"
              strokeWidth="2.5"
              strokeLinecap="round"
            />

            {/* Lower Lash Line & Dashes */}
            <path
              d="M 15 78 Q 45 92 75 78"
              stroke="#f8fafc"
              strokeWidth="2"
              fill="none"
              strokeDasharray="3,5"
            />

            {/* Beauty Mark / Mole under right eye */}
            <circle cx="84" cy="94" r="4" fill="#f8fafc" />
          </g>
        </svg>
      </div>

      {/* ================= BUTTON INTERFACE ================= */}
      <motion.button
        ref={buttonRef}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={onClick}
        whileHover={{ scale: 1.03 }}
        whileTap={{ scale: 0.97 }}
        transition={{ type: "spring", stiffness: 350, damping: 25 }}
        className="group relative flex h-14 w-80 items-center justify-center rounded-2xl border border-neutral-800 bg-neutral-950 px-6 font-mono text-xs font-bold tracking-widest text-neutral-300 shadow-[0_15px_40px_rgba(0,0,0,0.9)] backdrop-blur-2xl transition-all duration-300 hover:border-amber-600/60 hover:text-white hover:shadow-[0_20px_50px_rgba(217,119,6,0.25)]"
      >
        {/* Ambient Glow */}
        <div
          className={cn(
            "pointer-events-none absolute -inset-1 rounded-2xl bg-gradient-to-r from-amber-600/20 via-orange-500/10 to-amber-600/20 blur-xl transition-opacity duration-500",
            isHovered ? "opacity-100" : "opacity-30"
          )}
        />

        <span className="relative z-10 font-mono tracking-widest text-center transition-colors duration-200">
          {displayText}
        </span>
      </motion.button>
    </div>
  );
}
